"""Publish the verified Lab 03 step-by-step walkthrough with chapters and capture evidence."""
from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='managed-agents-lab03-walkthrough';P=R/'presentations'/N;V=R/'videos'/N
TITLE='Lab 03 Step by Step: Built-in Tools, Offline and Live'
r=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert r['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/r['file']).read_bytes()).hexdigest()==r['sha256']
